/**
 * Resource Version Policy
 *
 * How the system supports versioning for a resource.
 * - no-version: No VersionId Support
 * - versioned: Versioned
 * - versioned-update: VersionId tracked fully
 */
export type ResourceVersionPolicy =
  | "no-version"
  | "versioned"
  | "versioned-update";

/**
 * Response Type
 *
 * The kind of response to a message.
 * - ok: OK
 * - transient-error: Transient Error
 * - fatal-error: Fatal Error
 */
export type ResponseType = "ok" | "transient-error" | "fatal-error";

/**
 * Restful Capability Mode
 *
 * The mode of a RESTful capability statement.
 * - client: Client
 * - server: Server
 */
export type RestfulCapabilityMode = "client" | "server";

/**
 * Search Comparator
 *
 * What Search Comparator Codes are supported in search.
 * - eq: Equals
 * - ne: Not Equals
 * - gt: Greater Than
 * - lt: Less Than
 * - ge: Greater or Equals
 * - le: Less of Equal
 * - sa: Starts After
 * - eb: Ends Before
 * - ap: Approximately
 */
export type SearchComparator =
  | "eq"
  | "ne"
  | "gt"
  | "lt"
  | "ge"
  | "le"
  | "sa"
  | "eb"
  | "ap";

/**
 * Search Entry Mode
 *
 * Why an entry is in the result set - whether it's included as a match or because
 * of an _include requirement, or to convey information or warning information
 * about the search process.
 * - match: Match
 * - include: Include
 * - outcome: Outcome
 */
export type SearchEntryMode = "match" | "include" | "outcome";

/**
 * Search Modifier All Codes
 *
 * A supported modifier for a search parameter.
 * - missing: Missing
 * - exact: Exact
 * - contains: Contains
 * - not: Not
 * - text: Text
 * - in: In
 * - not-in: Not In
 * - below: Below
 * - above: Above
 * - type: Type
 * - identifier: Identifier
 * - of-type: Of Type
 * - code-text: Code Text
 * - text-advanced: Text Advanced
 * - iterate: Iterate
 */
export type SearchModifierAllCodes =
  | "missing"
  | "exact"
  | "contains"
  | "not"
  | "text"
  | "in"
  | "not-in"
  | "below"
  | "above"
  | "type"
  | "identifier"
  | "of-type"
  | "code-text"
  | "text-advanced"
  | "iterate";

/**
 * Search Modifier Code
 *
 * A supported modifier for a search parameter.
 * - missing: Missing
 * - exact: Exact
 * - contains: Contains
 * - not: Not
 * - text: Text
 * - in: In
 * - not-in: Not In
 * - below: Below
 * - above: Above
 * - type: Type
 * - identifier: Identifier
 * - of-type: Of Type
 * - code-text: Code Text
 * - text-advanced: Text Advanced
 * - iterate: Iterate
 */
export type SearchModifierCode =
  | "missing"
  | "exact"
  | "contains"
  | "not"
  | "text"
  | "in"
  | "not-in"
  | "below"
  | "above"
  | "type"
  | "identifier"
  | "of-type"
  | "code-text"
  | "text-advanced"
  | "iterate";

/**
 * SearchParamType
 *
 * Data types allowed to be used for search parameters.
 * - number: Number
 * - date: Date/DateTime
 * - string: String
 * - token: Token
 * - reference: Reference
 * - composite: Composite
 * - quantity: Quantity
 * - uri: URI
 * - special: Special
 * - resource: Resource
 */
export type SearchParamType =
  | "number"
  | "date"
  | "string"
  | "token"
  | "reference"
  | "composite"
  | "quantity"
  | "uri"
  | "special"
  | "resource";

/**
 * Search Processing Mode Type
 *
 * How a search parameter relates to the set of elements returned by evaluating its
 * expression query.
 * - normal: Normal
 * - phonetic: Phonetic
 * - other: Other
 */
export type SearchProcessingModeType = "normal" | "phonetic" | "other";

/**
 * SlicingRules
 *
 * How slices are interpreted when evaluating an instance.
 * - closed: Closed
 * - open: Open
 * - openAtEnd: Open at End
 */
export type SlicingRules = "closed" | "open" | "openAtEnd";

/**
 * Slot Status
 *
 * The free/busy status of the slot.
 * - busy: Busy
 * - free: Free
 * - busy-unavailable: Busy (Unavailable)
 * - busy-tentative: Busy (Tentative)
 * - entered-in-error: Entered in error
 */
export type SlotStatus =
  | "busy"
  | "free"
  | "busy-unavailable"
  | "busy-tentative"
  | "entered-in-error";

/**
 * SortDirection
 *
 * The possible sort directions, ascending or descending.
 * - ascending: Ascending
 * - descending: Descending
 */
export type SortDirection = "ascending" | "descending";

