/**
 * DeviceAlert
 *
 * Describes a physiological or technical alert condition report originated by a
 * device.  The DeviceAlert resource is derived from the ISO/IEEE 11073-10201
 * Domain Information Model standard, but is more widely applicable.
 *
 * @see {@link http://hl7.org/fhir/R6/DeviceAlert.html}
 */

export interface DeviceAlert extends DomainResource {
  readonly resourceType: "DeviceAlert";

  /**
   * An indication of whether (true) or not (false) the alert condition has been
   * acknowledged.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.acknowledged}
   * @fhirType boolean
   */
  acknowledged?: boolean | undefined;
  _acknowledged?: Element | undefined;

  /**
   * An indication of who or what acknowledged the alert condition.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.acknowledgedBy}
   */
  acknowledgedBy?:
    | Reference<
        Patient | Device | Practitioner | PractitionerRole | RelatedPerson
      >
    | undefined;

  /**
   * Partitions the device alert into one or more categories that can be used to
   * filter searching, to govern access control and/or to guide system behavior.
   * Categorization might be done automatically (inferred by code) or manually by
   * user assertion.  The absence of a category may limit the ability to determine
   * when the element should be handled, so strong consideration should be given to
   * how systems will be able to determine category values for legacy data and how
   * data that cannot be categorized will be handled.  As well, some categories might
   * not be mutually exclusive, so systems should prepare for multiple declared
   * categories - even within a single category 'axis'.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.category}
   */
  category?: Array<CodeableConcept> | undefined;

  /**
   * A code that indicates the specific condition that triggered the alert.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.code}
   */
  code: CodeableConcept;

  /**
   * The value causing the alert condition.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.derivedFrom}
   */
  derivedFrom?: Array<DeviceAlertDerivedFrom> | undefined;

  /**
   * Indicates the device that detected the alert condition. The device could be a
   * top-level Device or component Device (such as an MDS, VMD, or Channel); or might
   * identify the specific DeviceMetric of a Device (e.g., a heart rate reading) that
   * was in an alert condition.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.device}
   */
  device?: Reference<Device | DeviceMetric> | undefined;

  /**
   * The Encounter during which the alert condition was raised.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.encounter}
   */
  encounter?: Reference<Encounter> | undefined;

  /**
   * Business identifiers assigned to this alert, by the source device, gateway
   * software, manufacturers, or other systems or organizations. These identifiers
   * remain constant as the resource is updated and propagates from server to server.
   * Note: This is a business identifier, not a resource identifier (see
   * [discussion](resource.html#identifiers)).  It is best practice for the
   * identifier to only appear on a single resource instance, however business
   * practices may occasionally dictate that multiple resource instances with the
   * same identifier can exist - possibly even with different resource types. For
   * identifiers assigned to an alert by the device or gateway software, the `system`
   * element of the identifier might be set to an identifier of the device.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.identifier}
   */
  identifier?: Array<Identifier> | undefined;

  /**
   * The label might combine information from the alert code, priority, the
   * measurement type, measurement value, body sites and other sources, e.g., “HR >
   * 180”.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.label}
   * @fhirType string
   */
  label?: string | undefined;
  _label?: Element | undefined;

  /**
   * The principal physical location of the subject at the time the alert condition
   * occurred. This could be different from the location of the alerting device at
   * that time, and from the current location of either the subject or the alert
   * condition detecting device.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.location}
   */
  location?: Reference<Location> | undefined;

  /**
   * This element is used to record the date or time period when the alert condition
   * did occur or is occurring.
   * This element is used to record the time period during which the alert condition
   * is or was active. The status code allows differentiation of whether the timing
   * reflects a historic event or an ongoing event. A date/time value SHOULD be used
   * for instantaneous conditions. Partial date/time values are ambiguous about
   * whether they represent the condition occurring at some point in the partially
   * specified period, or for all of the period, and (absent additional guidance)
   * SHOULD be avoided. Ongoing events SHOULD not include a Period upper bound.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.occurrenceDateTime}
   * @fhirType dateTime
   */
  occurrenceDateTime?: string | undefined;
  _occurrenceDateTime?: Element | undefined;

  /**
   * This element is used to record the date or time period when the alert condition
   * did occur or is occurring.
   * This element is used to record the time period during which the alert condition
   * is or was active. The status code allows differentiation of whether the timing
   * reflects a historic event or an ongoing event. A date/time value SHOULD be used
   * for instantaneous conditions. Partial date/time values are ambiguous about
   * whether they represent the condition occurring at some point in the partially
   * specified period, or for all of the period, and (absent additional guidance)
   * SHOULD be avoided. Ongoing events SHOULD not include a Period upper bound.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.occurrencePeriod}
   */
  occurrencePeriod?: Period | undefined;

  /**
   * Whether the alert condition is currently active.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.presence}
   * @fhirType boolean
   */
  presence: boolean;
  _presence?: Element | undefined;

  /**
   * The alert priority is usually reported by the source device. A priority of
   * `info` SHOULD indicate that the alert is “for information only” and urgent
   * action is not required. The element MAY be omitted if the priority is unknown.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.priority}
   */
  priority?: CodeableConcept | undefined;

  /**
   * The procedure (or procedures) during which the alert condition was raised.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.procedure}
   */
  procedure?: Array<Reference<Procedure>> | undefined;

  /**
   * Annunciation or notification of the alert condition.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.signal}
   */
  signal?: Array<DeviceAlertSignal> | undefined;

  /**
   * The current state of the device alert.
   * Unknown does not represent "other" - one of the defined statuses must apply.
   * Unknown is used when the authoring system is not sure what the current status
   * is.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.status}
   * @see {@link DeviceAlertStatusCodes}
   * @fhirType code
   */
  status: DeviceAlertStatusCodes;
  _status?: Element | undefined;

  /**
   * Who or what the alert is about.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.subject}
   */
  subject: Reference<
    | Patient
    | Device
    | BiologicallyDerivedProduct
    | Group
    | Location
    | Medication
    | NutritionProduct
    | Specimen
  >;

  /**
   * physiological | technical.
   * @see {@link http://hl7.org/fhir/R6/DeviceAlert-definitions.html#DeviceAlert.type}
   */
  type?: CodeableConcept | undefined;
}

/**
 * DeviceAssociation
 *
 * A record of association of a device.
 *
 * @see {@link http://hl7.org/fhir/R6/DeviceAssociation.html}
 */

export interface DeviceAssociation extends DomainResource {
  readonly resourceType: "DeviceAssociation";

  /**
   * State of the device’s association (e.g., implanted, attached, on, off, standby,
   * defective).
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.associationStatus}
   */
  associationStatus?: CodeableConcept | undefined;

  /**
   * Current anatomical location of the device in/on subject.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.bodyStructure}
   */
  bodyStructure?: Reference<BodyStructure> | undefined;

  /**
   * Reference to the device that is being associated.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.device}
   */
  device: Reference<Device>;

  /**
   * The entity for which the device is being used, benefitting from the device, or
   * which the device is being operated upon, which is usually distinct from the
   * association subject, such as an operator or similar.
   * Consider the situation of a procedure, during which an anesthesiologist uses a
   * ventilator on a patient. Two associations would be recorded: one of the
   * ventilator associated to a subject patient with a treatment relationship; in the
   * other, the ventilator associated to the subject anesthesiologist with an
   * operator relationship. In the latter relationship, the patient would be recorded
   * as the `focus` to indicate that the anesthesiologist was using the device for
   * that patient.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.focus}
   */
  focus?:
    | Reference<
        | BiologicallyDerivedProduct
        | CareTeam
        | Device
        | Group
        | Location
        | Medication
        | NutritionProduct
        | Organization
        | Patient
        | Practitioner
        | PractitionerRole
        | RelatedPerson
        | Specimen
        | Substance
      >
    | undefined;

  /**
   * Instance identifier.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.identifier}
   */
  identifier?: Array<Identifier> | undefined;

  /**
   * Begin and end dates and times for the device association.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.period}
   */
  period?: Period | undefined;

  /**
   * Describes the relationship between the device and subject.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.relationship}
   */
  relationship?: Array<CodeableConcept> | undefined;

  /**
   * Indicates the state of the Device association.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.status}
   * @see {@link DeviceAssociationStatusCodes}
   * @fhirType code
   */
  status: DeviceAssociationStatusCodes;
  _status?: Element | undefined;

  /**
   * The reasons given for the current association status.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.statusReason}
   */
  statusReason?: Array<CodeableConcept> | undefined;

  /**
   * The individual, group of individuals or device that the device is on or
   * associated with.
   * The operation reflects a shorter term indication when the device is actually
   * being used for the subject and who the operator is.  The operator may be the
   * same as the subject, in which case it is less likely to have to document the
   * operation.  Where it is relevant to document periods of use, absence of the
   * operator cannot imply that the subject is the operator, thus would need to be
   * explicitly stated.
   * @see {@link http://hl7.org/fhir/R6/DeviceAssociation-definitions.html#DeviceAssociation.subject}
   */
  subject?:
    | Reference<
        | BiologicallyDerivedProduct
        | CareTeam
        | Device
        | Group
        | Location
        | Medication
        | NutritionProduct
        | Organization
        | Patient
        | Practitioner
        | PractitionerRole
        | RelatedPerson
        | Specimen
        | Substance
      >
    | undefined;
}

