/**
 * Goal
 *
 * Describes the intended objective(s) for a patient, group, or organizational
 * care.  Examples include a patient's weight loss, restoration of an activity of
 * daily living for a patient, obtaining herd immunity via immunization for a
 * group, meeting a process improvement objective for an organization, etc.
 *
 * @see {@link http://hl7.org/fhir/R6/Goal.html}
 */

export interface Goal extends DomainResource {
  readonly resourceType: "Goal";

  /**
   * Information about the acceptance and relative priority assigned to the goal by
   * the patient, practitioners and other stakeholders.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.acceptance}
   */
  acceptance?: Array<GoalAcceptance> | undefined;

  /**
   * Describes the progression, or lack thereof, towards the goal against the target.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.achievementStatus}
   */
  achievementStatus?: CodeableConcept | undefined;

  /**
   * The identified conditions and other resources that provide the context for why
   * the goal exists.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.addresses}
   */
  addresses?:
    | Array<
        Reference<
          | Condition
          | Observation
          | MedicationStatement
          | MedicationRequest
          | NutritionOrder
          | ServiceRequest
          | RiskAssessment
          | Procedure
          | NutritionIntake
        >
      >
    | undefined;

  /**
   * Indicates a category the goal falls within.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.category}
   */
  category?: Array<CodeableConcept> | undefined;

  /**
   * After meeting the goal, ongoing activity is needed to sustain the goal
   * objective.
   * For example, getting a yellow fever vaccination for a planned trip is a goal
   * that is designed to be completed (continuous = false).  A goal to sustain HbA1c
   * levels would not be a one-time goal (continuous = true).
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.continuous}
   * @fhirType boolean
   */
  continuous?: boolean | undefined;
  _continuous?: Element | undefined;

  /**
   * Human-readable and/or coded description of a specific desired objective of care,
   * such as "control blood pressure" or "negotiate an obstacle course" or "dance
   * with child at wedding".
   * If no code is available, use CodeableConcept.text.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.description}
   */
  description: CodeableConcept;

  /**
   * Business identifiers assigned to this goal by the performer or other systems
   * which remain constant as the resource is updated and propagates from server to
   * server.
   * This is a business identifier, not a resource identifier (see
   * [discussion](resource.html#identifiers)).  It is best practice for the
   * identifier to only appear on a single resource instance, however business
   * practices may occasionally dictate that multiple resource instances with the
   * same identifier can exist - possibly even with different resource types.  For
   * example, multiple Patient and a Person resource instance might share the same
   * social insurance number.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.identifier}
   */
  identifier?: Array<Identifier> | undefined;

  /**
   * The state of the goal throughout its lifecycle.
   * This element is labeled as a modifier because the lifecycleStatus contains codes
   * that mark the resource as not currently valid.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.lifecycleStatus}
   * @see {@link GoalLifecycleStatus}
   * @fhirType code
   */
  lifecycleStatus: GoalLifecycleStatus;
  _lifecycleStatus?: Element | undefined;

  /**
   * Any comments related to the goal.
   * May be used for progress notes, concerns or other related information that
   * doesn't actually describe the goal itself.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.note}
   */
  note?: Array<Annotation> | undefined;

  /**
 * Identifies the mutually agreed level of importance associated with
 * reaching/sustaining the goal.
 * Extensions are available to track priorities as established by each participant
 * (i.e. Priority from the patient's perspective, different practitioners'
 * perspectives, family member's perspectives)

The ordinal extension on Coding can
 * be used to convey a numerically comparable ranking to priority.  (Keep in mind
 * that different coding systems may use a "low value=important".
 * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.priority}
 */
  priority?: CodeableConcept | undefined;

  /**
   * Individual who recorded the record and takes responsibility for its content.
   * Because the recorder takes responsibility for accurately recording information
   * in the record, the recorder is the most recent author.  The recorder might or
   * might not be the source who established the goal. Using Group is only allowed
   * when the group represents a family or a household and should not represent
   * groups of Practitioners.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.recorder}
   */
  recorder?:
    | Reference<
        Practitioner | PractitionerRole | Patient | RelatedPerson | Group
      >
    | undefined;

  /**
   * Indicates whose goal this is - patient goal, practitioner goal, etc.
   * This is the individual or team responsible for establishing the goal, not
   * necessarily who recorded it. Using Group is only allowed when the group
   * represents a family or a household and should not represent groups of
   * Practitioners.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.source}
   */
  source?:
    | Reference<
        | Patient
        | Practitioner
        | PractitionerRole
        | RelatedPerson
        | CareTeam
        | Group
      >
    | undefined;

  /**
   * The date or event after which the goal should begin being pursued.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.startDate}
   * @fhirType date
   */
  startDate?: string | undefined;
  _startDate?: Element | undefined;

  /**
   * The date or event after which the goal should begin being pursued.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.startCodeableConcept}
   */
  startCodeableConcept?: CodeableConcept | undefined;

  /**
   * Identifies when the current achievement status took effect.  I.e. When achieved,
   * when improving, etc.
   * To see the date for past statuses, query history.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.statusDate}
   * @fhirType date
   */
  statusDate?: string | undefined;
  _statusDate?: Element | undefined;

  /**
   * Captures the reason for the current lifecycle status.
   * This will typically be captured for statuses such as rejected, on-hold or
   * cancelled, but could be present for others.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.statusReason}
   */
  statusReason?: Array<CodeableConcept> | undefined;

  /**
   * Identifies the patient, group or organization for whom the goal is being
   * established.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.subject}
   */
  subject: Reference<Patient | Group | Organization>;

  /**
   * Indicates what should be done by when.
   * When multiple targets are present for a single goal instance, all targets must
   * be met for the overall goal to be met.
   * @see {@link http://hl7.org/fhir/R6/Goal-definitions.html#Goal.target}
   */
  target?: Array<GoalTarget> | undefined;
}

