  /**
   * A plan or request that is fulfilled in whole or in part by this nutrition order.
   * @see {@link http://hl7.org/fhir/R6/NutritionOrder-definitions.html#NutritionOrder.basedOn}
   */
  basedOn?:
    | Array<
        Reference<
          CarePlan | NutritionOrder | ServiceRequest | RequestOrchestration
        >
      >
    | undefined;

  /**
   * The date and time that this nutrition order was requested.
   * @see {@link http://hl7.org/fhir/R6/NutritionOrder-definitions.html#NutritionOrder.dateTime}
   * @fhirType dateTime
   */
  dateTime: string;
  _dateTime?: Element | undefined;

  /**
   * An encounter that provides additional information about the healthcare context
   * in which this request is made.
   * @see {@link http://hl7.org/fhir/R6/NutritionOrder-definitions.html#NutritionOrder.encounter}
   */
  encounter?: Reference<Encounter> | undefined;

  /**
   * Feeding provided through the gastrointestinal tract via a tube, catheter, or
   * stoma that delivers nutrition distal to the oral cavity.
   * @see {@link http://hl7.org/fhir/R6/NutritionOrder-definitions.html#NutritionOrder.enteralFormula}
   */
