/**
 * PackagedProductDefinition
 *
 * A medically related item or items, in a container or package.
 *
 * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition.html}
 */

export interface PackagedProductDefinition extends DomainResource {
  readonly resourceType: "PackagedProductDefinition";

  /**
   * Additional information or supporting documentation about the packaged product.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.attachedDocument}
   */
  attachedDocument?: Array<Reference<DocumentReference>> | undefined;

  /**
   * Allows the key features to be recorded, such as "hospital pack", "nurse
   * prescribable", "calendar pack".
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.characteristic}
   */
  characteristic?:
    | Array<PackagedProductDefinitionPackagingProperty>
    | undefined;

  /**
   * A total of the complete count of contained items of a particular type/form,
   * independent of sub-packaging or organization. This can be considered as the pack
   * size. This attribute differs from containedItem.amount in that it can give a
   * single aggregated count of all tablet types in a pack, even when these are
   * different manufactured items. For example a pill pack of 21 tablets plus 7 sugar
   * tablets, can be denoted here as '28 tablets'. This attribute is repeatable so
   * that the different item types in one pack type can be counted (e.g. a count of
   * vials and count of syringes). Each repeat must have different units, so that it
   * is clear what the different sets of counted items are, and it is not intended to
   * allow different counts of similar items (e.g. not '2 tubes and 3 tubes').
   * Repeats are not to be used to represent different pack sizes (e.g. 20 pack vs.
   * 50 pack) - which would be different instances of this resource.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.containedItemQuantity}
   */
  containedItemQuantity?: Array<Quantity> | undefined;

  /**
   * Identifies if the package contains different items, such as when a drug product
   * is supplied with another item e.g. a diluent or adjuvant.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.copackagedIndicator}
   * @fhirType boolean
   */
  copackagedIndicator?: boolean | undefined;
  _copackagedIndicator?: Element | undefined;

  /**
   * Textual description. Note that this is not the name of the package or product.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.description}
   * @fhirType markdown
   */
  description?: string | undefined;
  _description?: Element | undefined;

  /**
   * A unique identifier for this package as whole - not the content of the package.
   * Unique instance identifiers assigned to a package by manufacturers, regulators,
   * drug catalogue custodians or other organizations.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.identifier}
   */
  identifier?: Array<Identifier> | undefined;

  /**
   * The legal status of supply of the packaged item as classified by the regulator.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.legalStatusOfSupply}
   */
  legalStatusOfSupply?:
    | Array<PackagedProductDefinitionLegalStatusOfSupply>
    | undefined;

  /**
   * Manufacturer of this package type. When there are multiple it means these are
   * all possible manufacturers.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.manufacturer}
   */
  manufacturer?: Array<Reference<Organization>> | undefined;

  /**
   * Allows specifying that an item is on the market for sale, or that it is not
   * available, and the dates and locations associated.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.marketingStatus}
   */
  marketingStatus?: Array<MarketingStatus> | undefined;

  /**
   * A name for this package. Typically what it would be listed as in a drug
   * formulary or catalogue, inventory etc.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.name}
   * @fhirType string
   */
  name?: string | undefined;
  _name?: Element | undefined;

  /**
   * The product this package model relates to, not the contents of the package (for
   * which see package.containedItem).
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.packageFor}
   */
  packageFor?: Array<Reference<MedicinalProductDefinition>> | undefined;

  /**
   * A packaging item, as a container for medically related items, possibly with
   * other packaging items within, or a packaging component, such as bottle cap
   * (which is not a device or a medication manufactured item).
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.packaging}
   */
  packaging?: PackagedProductDefinitionPackaging | undefined;

  /**
   * The status within the lifecycle of this item. A high level status, this is not
   * intended to duplicate details carried elsewhere such as legal status, or
   * authorization or marketing status.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.status}
   */
  status?: CodeableConcept | undefined;

  /**
   * The date at which the given status became applicable.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.statusDate}
   * @fhirType dateTime
   */
  statusDate?: string | undefined;
  _statusDate?: Element | undefined;

  /**
   * A high level category e.g. medicinal product, raw material, shipping/transport
   * container, etc.
   * @see {@link http://hl7.org/fhir/R6/PackagedProductDefinition-definitions.html#PackagedProductDefinition.type}
   */
  type?: CodeableConcept | undefined;
}

